diff --git a/src/sfnt/sfobjs.c b/src/sfnt/sfobjs.c
index 6ee4e5e93..d3cb7697e 100644
--- a/src/sfnt/sfobjs.c
+++ b/src/sfnt/sfobjs.c
@@ -572,20 +572,23 @@
     FT_TRACE2(( "sfnt_init_face: %p (index %d)\n",
                 (void *)face,
                 face_instance_index ));

     face_index = FT_ABS( face_instance_index ) & 0xFFFF;

     /* value -(N+1) requests information on index N */
     if ( face_instance_index < 0 && face_index > 0 )
       face_index--;

+    /* Note that `face_index` is also used to enumerate elements */
+    /* of containers like a Mac Resource; this means we must     */
+    /* check whether we actually have a TTC.                     */
     if ( face_index >= face->ttc_header.count )
     {
       if ( face_instance_index >= 0 )
         return FT_THROW( Invalid_Argument );
       else
         face_index = 0;
     }

     if ( FT_STREAM_SEEK( face->ttc_header.offsets[face_index] ) )
       return error;

diff --git a/src/sfnt/ttload.c b/src/sfnt/ttload.c
index c3a5fae2c..26c7301d3 100644
--- a/src/sfnt/ttload.c
+++ b/src/sfnt/ttload.c
@@ -528,21 +528,22 @@
    *   Loads any font table into client memory.
    *
    * @Input:
    *   face ::
    *     The face object to look for.
    *
    *   tag ::
    *     The tag of table to load.  Use the value 0 if you want
    *     to access the whole font file, else set this parameter
    *     to a valid TrueType table tag that you can forge with
-   *     the MAKE_TT_TAG macro.
+   *     the MAKE_TT_TAG macro.  Use value 1 to access the table
+   *     directory.
    *
    *   offset ::
    *     The starting offset in the table (or the file if
    *     tag == 0).
    *
    *   length ::
    *     The address of the decision variable:
    *
    *     If length == NULL:
    *       Loads the whole table.  Returns an error if
@@ -570,36 +571,55 @@
                     FT_Long    offset,
                     FT_Byte*   buffer,
                     FT_ULong*  length )
   {
     FT_Error   error;
     FT_Stream  stream;
     TT_Table   table;
     FT_ULong   size;


-    if ( tag != 0 )
+    if ( tag == 0 )
+    {
+      /* The whole font file. */
+      size = face->root.stream->size;
+    }
+    else if ( tag == 1 )
+    {
+      /* The currently selected font's table directory.            */
+      /*                                                           */
+      /* Note that `face_index` is also used to enumerate elements */
+      /* of containers like a Mac Resource; this means we must     */
+      /* check whether we actually have a TTC (with multiple table */
+      /* directories).                                             */
+      FT_Long  idx = face->root.face_index & 0xFFFF;
+
+
+      if ( idx >= face->ttc_header.count )
+        idx = 0;
+
+      offset += face->ttc_header.offsets[idx];
+      size    = 4 + 8 + 16 * face->num_tables;
+    }
+    else
     {
       /* look for tag in font directory */
       table = tt_face_lookup_table( face, tag );
       if ( !table )
       {
         error = FT_THROW( Table_Missing );
         goto Exit;
       }

       offset += table->Offset;
       size    = table->Length;
     }
-    else
-      /* tag == 0 -- the user wants to access the font file directly */
-      size = face->root.stream->size;

     if ( length && *length == 0 )
     {
       *length = size;

       return FT_Err_Ok;
     }

     if ( length )
       size = *length;
